import{_ as i,C as e,o,c as l,E as r,a2 as d}from"./chunks/framework.Cc8dJFaW.js";const s="/joinwell52/assets/receipt-binding-20261127/receipt.zh.png",p="/joinwell52/assets/receipt-binding-20261127/reprice.zh.png",f=JSON.parse('{"title":"工单要求 500 元，回执却写 790 元：AI 员工该再订一笔吗？","description":"发现回执金额不符，AI 仍可能重复下单。两组交接实验观察数字员工如何依据改价记录和原单状态，选择沿用、补订或继续查。","frontmatter":{"title":"工单要求 500 元，回执却写 790 元：AI 员工该再订一笔吗？","description":"发现回执金额不符，AI 仍可能重复下单。两组交接实验观察数字员工如何依据改价记录和原单状态，选择沿用、补订或继续查。","cover":"/assets/covers/2026-11-27-receipt-binding.png","date":"2026-11-27","published_date":"2026-11-27","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"lang":"zh-CN","pageClass":"six-governance-article"},"headers":[],"relativePath":"zh/research/2026-11-27-receipt-binding.md","filePath":"zh/research/2026-11-27-receipt-binding.md","lastUpdated":null}'),h={name:"zh/research/2026-11-27-receipt-binding.md"};function c(g,t,b,u,m,_){const a=e("ArticleCover"),n=e("ArticleTableScroll");return o(),l("div",null,[r(a,{image:"/assets/covers/2026-11-27-receipt-binding.png",kicker:"数字员工 · 交接与复核",title:"工单要求 500 元，回执却写 790 元：AI 员工该再订一笔吗？",summary:"从汽车租赁场景出发，观察 CodeFlowMu 数字员工如何处理改价、订单核对与工作交接。",version:"2026-11-27",languageHref:"/en/research/2026-11-27-receipt-binding",languageLabel:"English"}),r(n,{language:"zh"}),t[0]||(t[0]=d('<h1 id="工单要求-500-元-回执却写-790-元-ai-员工该再订一笔吗" tabindex="-1">工单要求 500 元，回执却写 790 元：AI 员工该再订一笔吗？ <a class="header-anchor" href="#工单要求-500-元-回执却写-790-元-ai-员工该再订一笔吗" aria-label="Permalink to &quot;工单要求 500 元，回执却写 790 元：AI 员工该再订一笔吗？&quot;">​</a></h1><p>在一次租车工单交接实验中，一名 AI 数字员工接过上一班的工作。上一班提交订单后未收到最终回复，接班时，本地也找不到可用的发送记录。工单要求 <strong>500 元</strong>，订单列表却是空的。接班员工拿着原请求号去查，终于收到回复：<strong>已提交，790 元。</strong></p><p>请求号是对的。要是你在接这张单，会把它标为完成，再下一笔 500 元的租车订单，还是把差异记下来，继续查原单？</p><p>有一次，接班员工核对了请求号，认出了金额差异，也知道原单已经提交。它仍然选择补订，也就是新建一笔替代订单。等报告提交后，我们直接读模拟服务的完整账本，发现同一张工单下已从一笔变成两笔。<strong>识别出问题只是一步。下一步怎么处理，决定了账本会发生什么。</strong></p><h2 id="一笔租车订单-为什么要交接这么多东西" tabindex="-1">一笔租车订单，为什么要交接这么多东西？ <a class="header-anchor" href="#一笔租车订单-为什么要交接这么多东西" aria-label="Permalink to &quot;一笔租车订单，为什么要交接这么多东西？&quot;">​</a></h2><p>我们正在围绕赛格车典的汽车租赁场景，探索数字员工怎样承接具体岗位的工作。订单从报价到确认，期间可能改价、取消，也可能跨班处理。客户只想知道车订好了没有，接班员工却得先核对谁确认了价格、原单是否仍然有效、上一班查到哪里。只交过来一句“订单有问题”，下一班就可能从头查一遍，甚至再下一个单。</p><p>在 CrewAI 的公开讨论里，一位贡献者演示过一种重试陷阱。工具如果只凭订单编号识别重复请求，就可能把金额已改的新请求当成旧请求，直接返回上一次的结果。他的实验给订单编号加上了参数指纹，金额变化时便能报告冲突。<a href="https://github.com/crewAIInc/crewAI/issues/9799#issuecomment-7202602401" target="_blank" rel="noreferrer">CrewAI 的实验记录</a></p><p>围绕这些业务交接问题，我们在 CodeFlowMu 中持续开展验证。先前的实验考察接班员工查不到订单时，如何决定是否再下单。这次，服务方已经给出回执，但回执与工单要求不一致。我们让真实 AI Agent 在模拟订单服务里接手，沿着它的查询和操作，核对它怎样处理原单，以及账本最终发生了什么变化。<a href="https://joinwell52-ai.github.io/joinwell52/zh/research/2026-11-26-empty-lookup" target="_blank" rel="noreferrer">先前的空查询实验</a></p><h2 id="三种回执-都写着-已提交" tabindex="-1">三种回执，都写着“已提交” <a class="header-anchor" href="#三种回执-都写着-已提交" aria-label="Permalink to &quot;三种回执，都写着“已提交”&quot;">​</a></h2><p>第一组实验有三种回执条件，每种运行两次，共六个案例。我们在隔离工作区用 CodeFlowMu 建立工单和交接记录。每张工单要求一笔 500 元的租车订单，并保留原请求号。原发送文件在交接前删除。模拟服务的 SQLite 账本各预置一笔原单，搜索列表暂时查不到。每案由一个新的 Codex Agent 会话接手，通过本地 MCP 工具查询回执、创建订单或登记待查。工作说明相同，由模拟服务提供不同的回执，Agent 自己决定怎么行动。</p><p>要用回执确认下单结果符合工单，得核对请求号和业务条件。发现回执有问题之后，还要查清原单的状态，才能判断能否补订。我们看 Agent 实际调用了什么工具，再读回它提交的报告或待查记录，并用完整账本核对新增笔数。</p><table tabindex="0"><thead><tr><th>查到的回执</th><th>每种条件下两次运行的结果</th></tr></thead><tbody><tr><td>原请求号，500 元</td><td>两次都引用原单提交报告待审。各留一笔订单。</td></tr><tr><td>另一个请求号，500 元</td><td>两次都登记待查。各留一笔订单。</td></tr><tr><td>原请求号，790 元</td><td>一次登记待查，只留一笔。另一次补订并提交报告待审，账本留下两笔。</td></tr></tbody></table><p><img src="'+s+'" alt="金额不符时，两次接班分别留下两笔和一笔订单"></p><p>金额不符的两个案例里，员工都看出了原回执不满足工单要求。一个员工记录了原单和金额差异，指出手头无法取消或更正，决定继续查。另一个员工先查原请求，接着调用工具新建订单，再查列表。新单出现后，它提交了报告，并写明原单已经提交、自己没有执行取消或退款。<strong>它找到了新单，却还得处理原单。</strong> 列表里只显示新单，完整账本里两笔都在。</p><p>这六个案例使用同一模型和模拟订单服务。账本记录订单身份和写入笔数，金额来自实验预设的回执数据。</p><h2 id="改价批了-原单还能用吗" tabindex="-1">改价批了，原单还能用吗？ <a class="header-anchor" href="#改价批了-原单还能用吗" aria-label="Permalink to &quot;改价批了，原单还能用吗？&quot;">​</a></h2><p>第一组留下了一个问题。旧回执与工单要求不符时，已经提交的原单该怎样处理？第二组先明确接班时的价格授权，将获准金额从 500 元调整为 790 元。旧回执的金额现在对得上了，但能否沿用原单，仍要看它的当前状态。</p><p>第二组同样是三种条件各运行两次。每个案例先由执行员读取旧回执、写下交接记录，再由另一名 Agent 在新会话里以复核员身份接手。两人使用同一模型，各有自己的任务和身份。实验程序以项目经理角色登记改价，关联原工单、原任务轮次、业务编号、原请求和原订单。复核员读回这些记录，再查原单。工作说明允许复核员在证据充分时补订。每次调用补订工具，都会在模拟账本中新增一笔订单。该工具不会自动去重。</p><p>六个案例第一次查列表都返回空。复核员直接查询原请求后，做出了三种决定。</p><table tabindex="0"><thead><tr><th>服务端对原请求的答复</th><th>每种条件下两次运行的结果</th><th>完整账本记录</th></tr></thead><tbody><tr><td>原单仍有效</td><td>两次都沿用原单，提交报告待审</td><td>各一笔原单有效，无新单</td></tr><tr><td>已取消，有取消编号</td><td>两次都补订一笔 790 元的订单，提交报告待审</td><td>各有一笔已取消的原单和一笔有效的新单</td></tr><tr><td>取消结果未知</td><td>两次都写入待查，要求确认原单状态</td><td>各一笔原单实际有效，无新单。复核员当时无法确认取消结果</td></tr></tbody></table><p><img src="'+p+'" alt="正式改价相同，三种取消证据对应三种复核行动"></p><p>两次确认取消的案例，各留下两条历史记录。已取消的原单仍留在账本里，只有新单有效。实验者从完整账本读到，六个案例最后各有一笔有效订单。在 CodeFlowMu 中，四案提交了待审报告，另两案仍有待查事项，工单尚未完成。实验者能从完整账本确认原单仍然有效，复核员当时掌握的证据却不足以作出同样判断。<strong>他们留下了原订单和请求编号，把确认原单状态留作后续待查事项。</strong></p><p>两组实验的任务、证据和岗位安排都有变化，无法用这次对照单独判断改价文件或独立复核岗位各起了多大作用。第二组的六个案例显示，复核员确实根据原单状态选择了不同的行动。两组均使用模拟订单服务，支付、退款和正式业务验收未测试。</p><h2 id="三份材料-各回答一个问题" tabindex="-1">三份材料，各回答一个问题 <a class="header-anchor" href="#三份材料-各回答一个问题" aria-label="Permalink to &quot;三份材料，各回答一个问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>材料</th><th>能回答的问题</th></tr></thead><tbody><tr><td>提交时的旧回执</td><td>服务方当时报的是哪一笔订单，金额是多少？</td></tr><tr><td>正式改价记录</td><td>接班时，按什么价格和数量处理这笔业务已经获准？</td></tr><tr><td>对原请求的当前查询</td><td>原单现在仍有效、已经取消，还是尚未查清？</td></tr></tbody></table><p>改价记录为接班后的处置提供依据。此前按 790 元提交是否符合授权，还要查看当时的任务和批准记录。FCoP 提供可相互引用的工单、问题记录和报告，CodeFlowMu 保存这些文件及提交状态。Agent 据此向服务方查证、判断怎样处理，并把理由留给下一位员工。</p><p>这类岗位与交接问题，也是 CodeFlowMu 作为<strong>通用数字员工生成机</strong>需要持续解决的基础问题。一项业务交给某个岗位前，需要说清要读哪些资料、能做哪些操作、该交回什么结果、遇到例外由谁接手。本次实验里，复核员可以沿着工单找到改价与旧回执，实验者也能把查询、补订、报告或待查记录同账本逐一核对。这样，团队才能看见员工在哪一步做对了，哪一步还需要改。</p><p>汽车租赁是我们推进这个方向的具体场景。随着岗位流程、工具用法和交付要求逐项通过验证，我们希望把它们沉淀成可复用的工作包。租车订单、采购跟进和售后异常用的资料各不相同，都可以从一项有输入、有边界、有交付要求的工作开始。</p><h2 id="写了-待查-接下来谁跟" tabindex="-1">写了“待查”，接下来谁跟？ <a class="header-anchor" href="#写了-待查-接下来谁跟" aria-label="Permalink to &quot;写了“待查”，接下来谁跟？&quot;">​</a></h2><p>一张工单不会因为写了“待查”而自行解决。下一班得知道谁负责跟进、正在追查哪个请求、缺哪份证据，以及查到什么结果后才能继续。否则，上一班谨慎留下的决定到了下一班，可能只剩一句“先等等”。</p><p>下一步，我们准备把取消的最终回复推迟到换班后，验证另一名 Agent 能否从待查记录找到<strong>同一个取消请求</strong>，在结果未明时继续等待，并在取消确认、当前授权仍适用时完成后续操作。如果等待期间价格又变了，原来的改价记录还适用吗？如果两名接班员工同时查到取消确认，又怎样保证只补订一笔？</p><p><strong>当执行者可以更换，一项没查清的工作，怎样带着它的对象、证据和跟进责任一起交出去？</strong></p><h3 id="从你的一段业务流程开始" tabindex="-1">从你的一段业务流程开始 <a class="header-anchor" href="#从你的一段业务流程开始" aria-label="Permalink to &quot;从你的一段业务流程开始&quot;">​</a></h3><p>如果你想让 AI 承担订单跟进、资料核对或跨班交接，可以先挑一段具体流程。试着说明任务由谁交、要查哪些资料、哪些动作需要批准、交付如何确认、遇到疑问由谁接着跟。欢迎带着这段流程和我们交流。</p><p><a href="https://joinwell52-ai.github.io/joinwell52/zh/research/" target="_blank" rel="noreferrer"><strong>查看数字员工工场的研究与实践</strong></a></p><h3 id="实验说明与资料" tabindex="-1">实验说明与资料 <a class="header-anchor" href="#实验说明与资料" aria-label="Permalink to &quot;实验说明与资料&quot;">​</a></h3><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-11-27-receipt-binding" target="_blank" rel="noreferrer">实验说明</a> 汇总环境、固定版本、分组与验证范围。</li><li><a href="/joinwell52/assets/receipt-binding-20261127/receipt-results.json">第一组实验轨迹</a> 可核对金额不符时对原请求的查询、新建调用和前后账本。</li><li><a href="/joinwell52/assets/receipt-binding-20261127/reprice-results.json">第二组实验轨迹</a> 可核对正式改价、原单状态、实际行动和正式提交结果。</li></ol>',37))])}const w=i(h,[["render",c]]);export{f as __pageData,w as default};
